// Lit la notification envoyée par le configurateur et choisit le texte du modèle.
// On relit le mail d'origine via $('Gmail Trigger') car le node "Marquer comme lu"
// a remplacé $json par sa propre sortie.
//
// normalize('NFC') : sans ça, un corps aux accents décomposés fait échouer
// l'extraction de "Modèle".
const body = ($('Gmail Trigger').item.json.text || '').normalize('NFC');

// Les regex sont ANCRÉES en début de ligne (^ + flag m). Sans l'ancrage, un
// client dont le nom contient "Email : pirate@exemple.com" ferait partir la
// réponse chez le pirate au lieu du vrai client (testé, la faille est réelle).
const grab = (re) => (body.match(re)?.[1] || '').trim();

const clientEmail = grab(/^Email\s*:\s*(\S+@\S+)\s*$/m);
const clientNom   = grab(/^Nom\s*:\s*(.+)$/m);
const modeleId    = grab(/^ModeleID\s*:\s*(\S+)\s*$/m);
const modele      = grab(/^Modèle\s*:\s*(.+)$/m);

// ---------------------------------------------------------------------------
// Un texte par modele. Remplacer chaque placeholder par le vrai texte.
// Variables disponibles dans le texte : {{nom}} et {{modele}}
// ---------------------------------------------------------------------------
const TEMPLATES = {
  'lift-x-43': `[A REMPLIR - texte LIFTX 4'3" : voir email-templates.md]`,
  'lift-x-48': `[A REMPLIR - texte LIFTX 4'8" : voir email-templates.md]`,
  'lift-x-52': `[A REMPLIR - texte LIFTX 5'2" : voir email-templates.md]`,
  'lift-5-44': `[A REMPLIR - texte LIFT5 4'4" PRO : voir email-templates.md]`,
  'lift-5-49': `[A REMPLIR - texte LIFT5 4'9" SPORT : voir email-templates.md]`,
  'lift-5-54': `[A REMPLIR - texte LIFT5 5'4" CRUISER : voir email-templates.md]`,
  'lift-5f-49': `[A REMPLIR - texte LIFT5 F 4'9" SPORT : voir email-templates.md]`,
  'lift-5f-54': `[A REMPLIR - texte LIFT5 F 5'4" CRUISER : voir email-templates.md]`
};

const FALLBACK = `[A REMPLIR - texte de secours si le modele n'est pas reconnu]`;

const aTemplate = Object.prototype.hasOwnProperty.call(TEMPLATES, modeleId);
const corps = (aTemplate ? TEMPLATES[modeleId] : FALLBACK)
  .split('{{nom}}').join(clientNom)
  .split('{{modele}}').join(modele);

if (!clientEmail) {
  throw new Error('Aucune adresse client trouvee dans la notification : ' + body.slice(0, 200));
}

return {
  json: {
    clientEmail,
    clientNom,
    modeleId,
    modele,
    aTemplate,
    emailBody: corps,
    emailSubject: 'Votre configuration ' + (modele || 'Lift') + ' - notre proposition',
  },
};

